import xml.etree.ElementTree as ET, glob, os, zipfile

# Check a PP XML file to see what the track code looks like in the XML itself
pp_files = glob.glob\(os.path.join\('2023 PPs', '*.xml'\)\)
if pp_files:
    tree = ET.parse\(pp_files[0]\)
    root = tree.getroot\(\)
    print\(f'Root tag: {root.tag}'\)
    print\(f'Root attribs: {root.attrib}'\)
    # Find track info in the XML
    for child in root:
        print\(f'  <{child.tag}> attribs={child.attrib}'\)
        if child.tag == 'Race' or 'race' in child.tag.lower\(\):
            for subchild in child:
                if 'track' in subchild.tag.lower\(\) or 'course' in subchild.tag.lower\(\):
                    print\(f'    <{subchild.tag}> text={subchild.text}'\)
                    for sc in subchild:
                        print\(f'      <{sc.tag}> text={sc.text}'\)
            break
else:
    # Try zip files
    zip_files = glob.glob\(os.path.join\('2023 PPs', '*.zip'\)\)[:1]
    if zip_files:
        with zipfile.ZipFile\(zip_files[0]\) as zf:
            xml_names = [n for n in zf.namelist\(\) if n.endswith\('.xml'\)]
            if xml_names:
                with zf.open\(xml_names[0]\) as f:
                    root = ET.parse\(f\).getroot\(\)
                    print\(f'From zip: Root tag: {root.tag}'\)
                    print\(f'Root attribs: {root.attrib}'\)
                    for child in list\(root\)[:2]:
                        print\(f'  <{child.tag}>'\)
                        for subchild in list\(child\)[:15]:
                            text = subchild.text.strip\(\) if subchild.text else None
                            print\(f'    <{subchild.tag}> = {text}'\)
